Lemma row_l r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= lam r.
Proof. wall (Tree.Ebinary Tree.Mul (Tree.Ebinary Tree.Div (Tree.Econst (Tree.Int 1)) (Tree.Econst (Tree.Int 2))) (Tree.Eunary Tree.Sqr tree_rho)) r th. Qed.

(* every energy condition, for every observer, at every point of the wall *)
Theorem shell_energy_conditions r th : 1 <= r <= 2 -> 0 <= th <= PI -> energy_conditions (tE r th) (ta r th) (td r th) (tS r th) (tx r th) (tT r th) (tP r th).
Proof.
  intros Hr Hth.
  apply (certified (tE r th) (ta r th) (td r th) (tS r th) (tx r th) (tT r th) (tP r th) (mu r) (lam r)).
  - pose proof (row_n0 r th Hr Hth). lra.
  - pose proof (row_n1 r th Hr Hth). lra.
  - pose proof (row_n2 r th Hr Hth). lra.
  - pose proof (row_n3 r th Hr Hth). lra.
  - pose proof (row_m r th Hr Hth). lra.
  - pose proof (row_s r th Hr Hth). lra.
  - pose proof (row_d0 r th Hr Hth). lra.
  - pose proof (row_d1 r th Hr Hth). lra.
  - pose proof (row_d2 r th Hr Hth). lra.
  - pose proof (row_d3 r th Hr Hth). lra.
  - pose proof (row_l r th Hr Hth). lra.
Qed.

